// Assemble the scoring request. The rubric comes from prompts/scoring.md and the
// output contract from agents/scoring/schema.json, both read from disk, so
// neither is restated here and neither can drift from this node.

const MODEL = $env.OLLAMA_SCORING_MODEL || 'qwen9-64k:latest';

function extractSystemPrompt(markdown) {
  const section = markdown.split(/^##\s+System prompt\s*$/m)[1];
  if (!section) throw new Error('prompts/scoring.md: no "## System prompt" heading found');
  const fence = section.match(/```[a-z]*\n([\s\S]*?)\n```/);
  if (!fence) throw new Error('prompts/scoring.md: no fenced block under "## System prompt"');
  const text = fence[1].trim();
  if (text.length < 200) throw new Error('prompts/scoring.md: system prompt looks truncated');
  return text;
}

// The rubric itself is the part of scoring.md above the system prompt. The model
// is told to apply it literally, so it has to be able to read it.
function extractRubric(markdown) {
  const start = markdown.indexOf('## The rubric');
  const end = markdown.indexOf('## System prompt');
  if (start === -1 || end === -1 || end <= start) {
    throw new Error('prompts/scoring.md: could not locate the rubric section');
  }
  return markdown.slice(start, end).trim();
}

const doc = $('Prompt To Text').first().json.data;

// One request per line in agents/offers.json. The infrastructure prompt is
// assembled exactly as before; the automation line has its own system prompt
// and rubric further down the same file, and shares the bands table.
function between(markdown, startHeading, endHeading) {
  const start = markdown.indexOf(startHeading);
  const end = markdown.indexOf(endHeading, start + 1);
  if (start === -1 || end === -1) {
    throw new Error('prompts/scoring.md: could not locate "' + startHeading + '" before "' + endHeading + '"');
  }
  return markdown.slice(start, end).trim();
}
function automationPrompt(markdown) {
  const section = markdown.split(/^##\s+Automation system prompt\s*$/m)[1];
  const fence = section && section.match(/```[a-z]*\n([\s\S]*?)\n```/);
  if (!fence) throw new Error('prompts/scoring.md: no fenced block under "## Automation system prompt"');
  return fence[1].trim() + '\n\n' + between(markdown, '## Automation rubric', '## Automation system prompt') +
    '\n\n' + between(markdown, '## Bands', '## Hard overrides');
}
const catalogue = JSON.parse($('Offers To Text').first().json.data);
const PROMPTS = {
  infrastructure: extractSystemPrompt(doc) + '\n\n' + extractRubric(doc),
  automation: automationPrompt(doc),
};
for (const line of Object.keys(catalogue.lines)) {
  if (!PROMPTS[line]) throw new Error('agents/offers.json names line "' + line + '" with no rubric in prompts/scoring.md');
}

const schema = JSON.parse($('Schema To Text').first().json.data);
delete schema.$schema;
delete schema.$id;
delete schema.title;

return $input.all().flatMap((item, index) => Object.keys(catalogue.lines).map((line) => {
  const c = item.json;
  const signals = c.signals || [];
  const people = c.people || [];

  const lines = [
    'COMPANY',
    'Name: ' + c.name,
    'Domain: ' + c.domain,
    'Industry: ' + (c.industry || 'unknown'),
    'Employee count: ' + (c.employee_count === null || c.employee_count === undefined ? 'unknown' : c.employee_count),
    'Description: ' + (c.description || 'unknown'),
    '',
    'TECHNOLOGY (from research, each item carries its own source)',
    JSON.stringify(c.tech_stack || [], null, 1),
    '',
    'HIRING SIGNALS (from research)',
    JSON.stringify(c.hiring_signals || [], null, 1),
    '',
    'SIGNALS TABLE (the evidence rows; source_url present means it is a fact, not an inference)',
    JSON.stringify(signals, null, 1),
    '',
    'PEOPLE',
    people.length ? JSON.stringify(people, null, 1) : 'None known. There is no route to a decision maker.',
    '',
    'RESEARCH CONFIDENCE: ' + c.research_confidence,
    '',
    'Score this company against the ' + (line === 'infrastructure' ? '' : line + ' ') +
      'rubric. Award points only for evidence above.',
    'Absent evidence scores zero, never "average".',
  ];

  return {
    pairedItem: { item: index },
    json: {
      agent_run_id: c.agent_run_id,
      company_id: c.company_id,
      name: c.name,
      domain: c.domain,
      line,
      model: MODEL,
      llm_request: {
        model: MODEL,
        temperature: 0.2,
        max_tokens: 4000,
        // qwen reasoning models spend their whole budget thinking: 25000
        // characters of reasoning against 1000 of answer, and 218 seconds
        // against 13. The rubric is explicit enough that the visible answer is
        // as good without it. See docs/ollama.md.
        reasoning_effort: 'none',
        messages: [
          { role: 'system', content: PROMPTS[line] },
          { role: 'user', content: lines.join('\n') },
        ],
        response_format: {
          type: 'json_schema',
          json_schema: { name: 'scoring', strict: true, schema },
        },
      },
    },
  };
}));

// Validate the scoring response, then apply the mechanical guards.
//
// The rubric in prompts/scoring.md already states rules that are checkable
// against the database - "only count technology with a source", "an empty
// technology array scores 0", "reasonable_inferences can reach at most 12",
// "posted within 60 days". A model that is not well calibrated will not obey
// them reliably, so they are enforced here rather than trusted. Every cap is
// recorded, so a run can be explained later.
//
// docs/architecture.md: the rules that matter are enforced, not requested.

const schema = JSON.parse($('Schema To Text').first().json.data);
const claims = $('Claim And Open Run').all();
const requests = $('Build Scoring Request').all();

const COMPONENTS = {
  company_fit: 20, technology_fit: 20, hiring_signal: 20,
  pain_evidence: 20, decision_maker: 10, commercial_potential: 10,
};

// Anything that sells the same service is a competitor, not a prospect.
const COMPETITOR_PATTERNS = [
  /\bdevops\b[^.]{0,40}\b(consult|agency|partner|services)/i,
  /\b(sre|site reliability)\b[^.]{0,40}\b(consult|agency|services)/i,
  /\bplatform engineering\b[^.]{0,40}\b(consult|agency|services)/i,
  /\b(cloud|kubernetes)\b[^.]{0,30}\bconsultanc/i,
  /\bmanaged service provider\b/i,
];

// ---- the automation line ------------------------------------------------
//
// Build Scoring Request sends every company twice, once per line in
// agents/offers.json, and this node keeps the better of the two (see the end).
// The infrastructure guards below are unchanged and apply to that line only;
// the automation line has its own, from the automation rubric in
// prompts/scoring.md.
const INFRA = 'infrastructure';
const catalogue = JSON.parse($('Offers To Text').first().json.data);
const lineOf = (code) => (catalogue.offers.find((o) => o.code === code) || {}).line || null;

const AUTOMATION_COMPETITOR_PATTERNS = [
  /\b(automation|integration|rpa|workflow|no-?code|low-?code)\b[^.]{0,40}\b(agency|consult|partner|services)/i,
  /\b(zapier|make\.com|n8n|power automate|uipath)\b[^.]{0,30}\b(partner|agency|expert)/i,
];
// The signals that say there is repetitive work to automate. hiring_automation
// is deliberately absent: it says the opposite - they are buying the solution.
const AUTOMATION_EVIDENCE = ['hiring_manual_ops', 'manual_process', 'tool_sprawl', 'volume_growth'];
// Roles whose job is repetitive back-office work, and roles that automate it.
const OPS_ROLE = /\b(operations|ops) (coordinator|associate|specialist|assistant|administrator|executive)\b|data entry|order (processing|management)|fulfil+ment|dispatch|back.?office|billing|accounts? (payable|receivable)|bookkeep|admin(istrative)? assistant|customer (support|service|success) (agent|representative|associate)|reporting (analyst|specialist)|logistics coordinator/i;
const AUTOMATION_ROLE = /automation|revops|revenue operations|internal tools|business systems|integrations? engineer|systems analyst|\brpa\b/i;

const claimByCompany = new Map(claims.map((c) => [c.json.company_id, c.json]));
const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const req = requests[i].json;
  // Two requests per company, so the claim is found by company, not by index.
  const claim = claimByCompany.get(req.company_id);
  const line = req.line || INFRA;
  const res = $input.all()[i].json ?? {};

  const errors = [];
  const notes = [];
  const overrides = [];
  let parsed = null;
  let raw = '';
  let usage = null;

  if (res.error !== undefined) {
    const e = res.error;
    errors.push('Scoring model request failed: ' +
      (typeof e === 'string' ? e : (e && e.message) || JSON.stringify(e)));
  } else {
    usage = res.usage ?? null;
    const choice = Array.isArray(res.choices) ? res.choices[0] : null;
    if (!choice) {
      errors.push('Response contained no choices');
    } else if (choice.finish_reason === 'length') {
      errors.push('Response hit the token limit and is truncated. Use a model with a ' +
        'larger context window (OLLAMA_SCORING_MODEL)');
    } else {
      raw = (choice.message && choice.message.content) || '';
      if (!raw.trim()) {
        errors.push('Model returned no text content');
      } else {
        try { parsed = JSON.parse(raw); } catch (e) {
          errors.push('Response is not valid JSON: ' + e.message);
        }
      }
    }
  }

  if (parsed !== null && (typeof parsed !== 'object' || Array.isArray(parsed))) {
    errors.push('Response is valid JSON but not a JSON object');
    parsed = null;
  }

  if (parsed !== null) {
    for (const key of schema.required) {
      if (!(key in parsed)) errors.push('Missing required key: ' + key);
    }
    for (const key of Object.keys(COMPONENTS)) {
      const c = parsed[key];
      if (!c || typeof c !== 'object' || typeof c.points !== 'number') {
        errors.push(key + ' must be an object with numeric points');
      } else if (!Number.isInteger(c.points) || c.points < 0 || c.points > COMPONENTS[key]) {
        errors.push(key + '.points must be an integer 0-' + COMPONENTS[key] + ', got ' + c.points);
      }
    }
    // recommended_offer and total_score are recorded, not used: the offer is
    // carried through from research and the total is a generated column. The
    // json_schema constrains keys and types but NOT enums or numeric bounds -
    // this model has returned a band in the offer field and a total of 109 -
    // so nothing downstream may depend on either.
  }

  if (errors.length) {
    results.push({ index: i, line, json: {
      agent_run_id: req.agent_run_id, company_id: req.company_id,
      name: req.name, domain: req.domain,
      valid: false, errors, notes: [], overrides: [],
      error_message: 'Scoring validation failed: ' + errors.join('; '),
      scores: null, lead: null, raw_response: raw, usage,
    } });
    continue;
  }

  // ---- mechanical guards --------------------------------------------------
  const points = {};
  for (const key of Object.keys(COMPONENTS)) points[key] = parsed[key].points;

  const signals = claim.signals || [];
  const people = claim.people || [];
  const tech = Array.isArray(claim.tech_stack) ? claim.tech_stack : [];
  const hiring = Array.isArray(claim.hiring_signals) ? claim.hiring_signals : [];

  function cap(key, ceiling, why) {
    if (points[key] > ceiling) {
      overrides.push(key + ' capped ' + points[key] + ' -> ' + ceiling + ': ' + why);
      points[key] = ceiling;
    }
  }

  // "Only count technology with a source. An empty technology array scores 0."
  const sourcedTech = tech.filter((t) => t && typeof t === 'object' && t.source);
  const automationSignals = signals.filter((s) => s && AUTOMATION_EVIDENCE.includes(s.signal_type));
  if (line === INFRA) {
    if (!sourcedTech.length) cap('technology_fit', 0, 'no technology with a source');
  } else if (!automationSignals.length) {
    cap('technology_fit', 0, 'no automation-line signal: no evidence of repetitive work');
  }

  // "reasonable_inferences can reach at most 12. Above that requires a fact
  //  with a source." A signals row with a source_url is that fact.
  // On the automation line only automation-line signals count as its pain.
  const lineSignals = line === INFRA ? signals : automationSignals;
  const sourcedSignals = lineSignals.filter((s) => s && s.source_url);
  if (!lineSignals.length) cap('pain_evidence', 0, 'no signals at all for this line');
  else if (!sourcedSignals.length) cap('pain_evidence', 12, 'no signal carries a source_url');

  // ---- capacity gap, formerly hiring signal -------------------------------
  //
  // This guard used to read: cap hiring_signal at 17 unless a senior
  // infrastructure role was posted within 60 days. Under the inverted rubric
  // that is backwards in both directions - it withheld the top band from the
  // companies that qualify for it and reserved it for the ones that no longer
  // do. See docs/scoring.md.
  const now = Date.now();
  const analysis = claim.analysis || {};

  // infra_people_found === 0 is the strongest signal this rubric has, and it is
  // the one the research model cannot be trusted to report. Asked about Monzo -
  // a bank with a large platform organisation - it wrote two absence_checks
  // entries both saying result 'unreadable', meaning it could not open a team
  // page at all, and then wrote infra_people_found: 0 anyway. The prompt says
  // in as many words to write null in that case. It wrote 0.
  //
  // So the number is derived from the evidence rather than read from the field.
  // A counted zero requires at least one absence_check that actually came back
  // 'absent'; without one the answer is null, which scores as ignorance.
  //
  // Only this direction is enforced. A non-zero count can stand unverified,
  // because it can only ever lower the score, and being wrong in the direction
  // of not sending an email costs nothing.
  const checks = Array.isArray(analysis.absence_checks) ? analysis.absence_checks : [];
  const countedAbsence = checks.some((a) => a && a.result === 'absent');
  const claimedInfra = analysis.infra_people_found;
  let infraPeople = claimedInfra;
  if (claimedInfra === 0 && !countedAbsence) {
    infraPeople = null;
    const how = checks.length
      ? checks.map((a) => a && a.result).filter(Boolean).join(', ')
      : 'no absence_checks at all';
    overrides.push('infra_people_found 0 discarded: no absence_check came back "absent" (' +
      how + '). Treated as null, which is what it means.');
  }

  // The research agent's own list carries is_infrastructure and days_open;
  // companies.hiring_signals is the fallback and carries neither.
  const researchRoles = Array.isArray(analysis.hiring_signals) ? analysis.hiring_signals : [];
  const roles = (researchRoles.length ? researchRoles : hiring)
    .filter((h) => h && typeof h === 'object');

  // Either signal is enough to call a role infrastructure. The model mislabels
  // in both directions - it marked "Threat and Analytics Lead" as
  // infrastructure and has missed obvious ones - and of the two mistakes only
  // under-labelling is expensive: an over-labelled role lowers the score, which
  // at worst costs an email that was never going to land.
  // "systems" alone was in this pattern and made "Frontend Design Systems
  // Engineer" an infrastructure role (Seeq, 2026-09-23), which moved the
  // company into the "infrastructure role open past 120 days" band. Only
  // systems roles that operate machines count now.
  const INFRA_ROLE = /devops|\bsre\b|site reliability|platform|infrastructure|cloud|sysadmin|systems (administrator|admin)\b|(?<!design |distributed |embedded )systems engineer|production engineer/i;
  const isInfra = (h) => h.is_infrastructure === true || INFRA_ROLE.test(String(h.role || ''));

  // posted_at wins over days_open, and that order is not a preference.
  // days_open is the model's own arithmetic and it cannot do arithmetic: for
  // GoCardless it returned posted_at 2026-06-11 with days_open 354, on a day
  // when the answer was 103, and 2026-08-26 with 349 when the answer was 27.
  // The inflated numbers put an SRE role two bands above where it belonged.
  //
  // posted_at is not the model's invention - WF-02 renders "[posted
  // YYYY-MM-DD]" into the material straight from the job board, so the model
  // is copying a date rather than computing one, which is the only part of
  // this it can be relied on for.
  const daysOpen = (h) => {
    const posted = h.posted_at ? Date.parse(h.posted_at) : NaN;
    if (Number.isFinite(posted)) {
      const days = Math.floor((now - posted) / 86400000);
      // A date in the future is a hallucinated date, not a role opening later.
      return days >= 0 ? days : null;
    }
    return Number.isInteger(h.days_open) && h.days_open >= 0 ? h.days_open : null;
  };

  const infraRoles = roles.filter(isInfra);
  const productRoles = roles.filter((h) => !isInfra(h));
  // Named, not just counted. A cap this strong has to say which advert caused
  // it: the model labels roles as infrastructure that plainly are not - "Threat
  // and Analytics Lead" among them - and an override reading "an infrastructure
  // role was posted within 60 days" with no role attached is unauditable.
  const dated = infraRoles.map((h) => ({ role: String(h.role || 'unnamed role'), days: daysOpen(h) }))
                          .filter((x) => x.days !== null);
  const infraAges = dated.map((x) => x.days);
  const freshest = dated.filter((x) => x.days <= 60).sort((a, b) => a.days - b.days)[0] || null;
  const oldest = dated.filter((x) => x.days > 120).sort((a, b) => b.days - a.days)[0] || null;
  const freshInfra = freshest !== null;
  const staleInfra = oldest !== null;
  const nameIt = (x) => '"' + x.role + '", ' + x.days + ' days open';
  // An infrastructure role with no date is treated as fresh. Guessing the
  // other way turns an unknown into the 13-17 band, which is the one that
  // says "they cannot hire it" - a claim no date supports.
  const undatedInfra = infraRoles.length > infraAges.length;

  // Automation line: the same shape as the infrastructure chain below, with
  // automation roles in place of infrastructure roles and back-office roles in
  // place of product engineering ones.
  const autoRoles = roles.filter((h) => AUTOMATION_ROLE.test(String(h.role || '')));
  const autoDated = autoRoles.map((h) => ({ role: String(h.role || 'unnamed role'), days: daysOpen(h) }))
                             .filter((x) => x.days !== null);
  const freshAuto = autoDated.filter((x) => x.days <= 60).sort((a, b) => a.days - b.days)[0] || null;
  const staleAuto = autoDated.filter((x) => x.days > 120).sort((a, b) => b.days - a.days)[0] || null;
  // An undated automation role, or a hiring_automation signal with no role
  // behind it, is treated as recent - the same reasoning as undatedInfra.
  const undatedAuto = autoRoles.length > autoDated.length ||
    (!autoRoles.length && signals.some((s) => s && s.signal_type === 'hiring_automation'));
  const opsCount = Math.max(
    roles.filter((h) => !isInfra(h) && OPS_ROLE.test(String(h.role || ''))).length,
    signals.filter((s) => s && s.signal_type === 'hiring_manual_ops').length);

  if (line !== INFRA) {
    if (freshAuto || undatedAuto) {
      cap('hiring_signal', 0, freshAuto
        ? 'automation role posted within 60 days, ' + nameIt(freshAuto) + ': they are building it themselves'
        : 'an automation role is open with no date; treated as recent');
    } else if (staleAuto) {
      cap('hiring_signal', 17, 'automation role open past 120 days, ' + nameIt(staleAuto) + ': real need, unfilled');
    } else if (autoRoles.length) {
      cap('hiring_signal', 2, 'an automation role is open, 60-120 days');
    } else if (opsCount >= 2) {
      // The top band stays available: people hired for repetitive work.
    } else if (opsCount === 1) {
      cap('hiring_signal', 17, 'one open back-office role');
    } else {
      cap('hiring_signal', 7, 'no back-office hiring evidence either way');
    }
  } else if (freshInfra || undatedInfra) {
    cap('hiring_signal', 0, freshInfra
      ? 'infrastructure role posted within 60 days, ' + nameIt(freshest) + ': they are hiring the solution'
      : 'an infrastructure role is open with no date; treated as recent');
  } else if (staleInfra) {
    cap('hiring_signal', 17, 'infrastructure role open past 120 days, ' + nameIt(oldest) +
      ': real need, unfilled');
  } else if (infraRoles.length) {
    cap('hiring_signal', 2, 'an infrastructure role is open, 60-120 days');
  } else if (productRoles.length >= 2) {
    // The top band stays available: engineering roles open, none of them infra.
  } else if (productRoles.length === 1) {
    cap('hiring_signal', 12, 'only one open engineering role');
  } else {
    cap('hiring_signal', 7, 'no hiring evidence either way');
  }

  // Size. "A company above roughly 150 engineers has a platform team whether or
  // not it is visible, and a procurement process a solo consultant cannot
  // economically enter." That sentence was in the rubric and nowhere in the
  // code, which left it to a model that cannot read a team page to work out
  // that a bank employs infrastructure engineers.
  //
  // employee_count is whole-company where it comes from the YC directory, so
  // the thresholds are whole-company too: about 150 engineers sits near 400
  // people. Null does nothing - a company discovered from a job posting carries
  // no headcount, and a missing number is not a small company.
  //
  // This has to sit with the other component caps, above, and not with the hard
  // overrides below: by the time those run, fit has already been summed and a
  // cap on points.company_fit changes nothing. The first version of this guard
  // was written down there and the 150-400 branch was dead on arrival.
  const headcount = Number(claim.employee_count);
  if (line !== INFRA && Number.isFinite(headcount) && headcount > 300 && headcount <= 400) {
    cap('company_fit', 12, headcount + ' people is above the band the automation rubric sells into');
  }
  if (line === INFRA && Number.isFinite(headcount) && headcount > 150 && headcount <= 400) {
    cap('company_fit', 12, headcount + ' people is above the band this rubric sells into');
  }

  // ---- the counted absence gates the two top bands ------------------------
  //
  // company_fit 18-20 and technology_fit 18-20 both read "and no infra people
  // found". That is only a finding when somebody counted: infra_people_found
  // must be the integer 0, not null. A model that scores the top band on
  // silence is buying on ignorance, which is the one calibration error this
  // rubric can make that looks like success from every other angle.
  if (line === INFRA && infraPeople !== 0) {
    const seen = infraPeople === null || infraPeople === undefined
      ? 'nobody counted (infra_people_found is null)'
      : infraPeople + ' infrastructure people were found';
    cap('company_fit', 17, 'top band needs a counted absence: ' + seen);
    cap('technology_fit', 12, 'operational load is only the top band when nobody owns it: ' + seen);
  }

  // Decision maker is fully mechanical - it is a property of the people table,
  // not a judgement. The model's number is replaced, not capped.
  let dm = 0;
  let dmWhy = 'no person known';
  // Process work is bought by whoever runs operations, not only by engineering.
  const DM_TITLE = line === INFRA
    ? /cto|chief tech|vp eng|vice president|head of|director|founder|owner/i
    : /ceo|chief exec|coo|chief operat|operations|managing director|general manager|founder|owner|head of|director|cto|chief tech/i;
  // A role contact (kind 'role', 0022_role_contacts.sql) is the company's
  // published general address - info@, office@ - with no person behind it. It
  // is never a decision maker and never competes with a named person: it is
  // the recipient only when no named person has a usable address. Everything
  // below that ranks people ranks named people only, exactly as before.
  const named = people.filter((p) => String(p.kind || 'person') !== 'role');
  const roleContacts = people.filter((p) => String(p.kind || 'person') === 'role');
  const decisionMakers = named.filter((p) =>
    DM_TITLE.test(String(p.title || '')) ||
    ['c_level', 'vp', 'head', 'director', 'founder'].includes(String(p.seniority || '')));
  // Pick the recipient deliberately. Taking the first row was fine while there
  // was at most one person; WF-03 writes several at once and the order it
  // returns them in means nothing, so a CTO with a published address lost to a
  // VP with a derived one purely by position in the array.
  //
  // Ranked on three things, in this order:
  //   1. is this a decision maker at all - a published address on a junior is
  //      still the wrong person to write to
  //   2. how the address was obtained - docs/security.md treats a bounce as
  //      unrecoverable damage to the sending domain, so a published address
  //      beats one this system derived
  //   3. seniority, as the tiebreak
  const contactable = (p) => Boolean(p.email) &&
    ['valid', 'catch_all', 'guessed'].includes(String(p.email_status));
  const ADDRESS_RANK = { valid: 3, catch_all: 2, guessed: 1 };
  const SENIORITY_RANK = { c_level: 5, vp: 4, head: 3, director: 3, manager: 2, lead: 2, senior: 1 };
  const decisionMakerIds = new Set(decisionMakers.map((p) => p.person_id));

  const rank = (p) => [
    decisionMakerIds.has(p.person_id) ? 1 : 0,
    contactable(p) ? (ADDRESS_RANK[String(p.email_status)] || 0) : 0,
    SENIORITY_RANK[String(p.seniority)] || 0,
  ];
  const best = [...named].sort((a, b) => {
    const ra = rank(a);
    const rb = rank(b);
    for (let k = 0; k < ra.length; k++) if (rb[k] !== ra[k]) return rb[k] - ra[k];
    return 0;
  })[0] || null;
  // Decided on 2026-09-24: the general address may be written to when
  // no named person can be. Named people always win, so it is used only when
  // not one of them has a usable address.
  const roleRecipient = named.some(contactable) ? null : (roleContacts.find(contactable) || null);
  if (best && best.email && best.email_status === 'valid') { dm = 10; dmWhy = 'named decision maker with a verified email'; }
  else if (best && best.email) { dm = 7; dmWhy = 'named decision maker, email ' + best.email_status; }
  else if (best) { dm = 4; dmWhy = 'person named but no email'; }
  // Reaches the company, not a decision maker: below a named person with no
  // address, which at least says who decides.
  else if (roleRecipient) { dm = 3; dmWhy = 'no named person; only the general address ' + roleRecipient.email; }
  if (points.decision_maker !== dm) {
    overrides.push('decision_maker set to ' + dm + ' from the people table (model said ' +
      points.decision_maker + '): ' + dmWhy);
    points.decision_maker = dm;
  }

  let fit = points.company_fit + points.technology_fit + points.commercial_potential;
  let research = points.hiring_signal + points.pain_evidence;
  let dmScore = points.decision_maker;

  // ---- hard overrides -----------------------------------------------------
  let status = 'scored';
  let ceiling = 100;

  if (claim.domain_suppressed) {
    status = 'suppressed';
    ceiling = 0;
    overrides.push('domain is on the suppression list: company suppressed, no lead');
  }

  const haystack = [claim.name, claim.industry, claim.description].filter(Boolean).join(' ');
  if ((line === INFRA ? COMPETITOR_PATTERNS : AUTOMATION_COMPETITOR_PATTERNS).some((re) => re.test(haystack))) {
    ceiling = Math.min(ceiling, 39);
    overrides.push('sells the same service: forced to IGNORE');
  }

  // "A company above roughly 150 engineers has a platform team whether or not it
  // is visible, and a procurement process a solo consultant cannot economically
  // enter." That sentence was in the rubric and nowhere in the code, which left
  // it to a model that cannot read a team page to work out that a bank employs
  // infrastructure engineers.
  //
  // employee_count is whole-company where it comes from the YC directory, so
  // the thresholds are whole-company too: about 150 engineers sits near 400
  // people. Null does nothing - most companies discovered from a job posting
  // carry no headcount, and a missing number is not a small company.
  if (Number.isFinite(headcount) && headcount > 400) {
    ceiling = Math.min(ceiling, 39);
    overrides.push(headcount + ' people: large enough to have a platform team and a ' +
      'procurement process, forced to IGNORE');
  }

  // Nothing to operate, nothing to audit. Distinct from null, which only means
  // the research could not establish it and is handled by the confidence cap.
  if (line === INFRA && analysis.runs_production === false) {
    ceiling = Math.min(ceiling, 39);
    overrides.push('runs_production is false: nothing to operate, forced to IGNORE');
  }

  // They employ the person being sold.
  if (line === INFRA && Number.isInteger(infraPeople) && infraPeople > 0) {
    ceiling = Math.min(ceiling, 39);
    overrides.push(infraPeople + ' infrastructure people found on a page that was read: ' +
      'forced to IGNORE, they employ the person being sold');
  }

  // A cap rather than an IGNORE on purpose: the company is a real prospect on a
  // delay. When the role passes 120 days unfilled the capacity-gap band moves
  // it back up on its own.
  if (line === INFRA && (freshInfra || undatedInfra)) {
    ceiling = Math.min(ceiling, 59);
    overrides.push(freshInfra
      ? 'infrastructure role posted within 60 days, ' + nameIt(freshest) + ': capped at 59, ' +
        'they have the budget approved and will fill it'
      : 'an infrastructure role is open with no date: capped at 59, because the ' +
        'reading that sends an email is the one the evidence does not support');
  }

  if (line !== INFRA && !automationSignals.length) {
    ceiling = Math.min(ceiling, 39);
    overrides.push('no automation-line signal at all: nothing to audit, forced to IGNORE');
  }
  if (line !== INFRA && (freshAuto || undatedAuto)) {
    ceiling = Math.min(ceiling, 59);
    overrides.push(freshAuto
      ? 'automation role posted within 60 days, ' + nameIt(freshAuto) + ': capped at 59'
      : 'an automation role is open with no date: capped at 59');
  }

  const confidence = Number(claim.research_confidence);
  if (!Number.isFinite(confidence) || confidence < 0.3) {
    ceiling = Math.min(ceiling, 39);
    overrides.push('research confidence ' + claim.research_confidence +
      ' is below 0.3: total capped at 39 until re-researched');
  }

  // Reduce research first, then fit: when the cap is because the evidence is not
  // trustworthy, the evidence-derived half is the half to discount.
  let total = fit + research + dmScore;
  if (total > ceiling) {
    const take = total - ceiling;
    const fromResearch = Math.min(research, take);
    research -= fromResearch;
    const fromFit = Math.min(fit, take - fromResearch);
    fit -= fromFit;
    const fromDm = Math.min(dmScore, take - fromResearch - fromFit);
    dmScore -= fromDm;
    total = fit + research + dmScore;
  }

  // The database recomputes total_score and score_band as generated columns. A
  // disagreement is recorded, not corrected: docs/scoring.md says the database
  // value stands.
  if (parsed.total_score !== total) {
    notes.push('model total ' + parsed.total_score + ' differs from the stored total ' + total +
      '; the database value stands');
  }

  // A lead needs a person. Without WF-03 there are none, so no lead is created
  // and the company simply stays scored.
  // docs/scoring.md: a suppressed domain gets no lead at all, not a suppressed
  // one. Nothing downstream should ever have a row to reconsider.
  // The offer belongs to the line. On infrastructure it is carried through from
  // research as before, unless research picked an offer from the other line;
  // on automation it is the line's default, the process audit.
  const offers = schema.properties.recommended_offer.enum;
  const researchOffer = offers.includes(claim.research_offer) ? claim.research_offer : 'none';
  const offer = line !== INFRA ? catalogue.lines[line].default_offer
    : (researchOffer === 'none' || lineOf(researchOffer) === INFRA) ? researchOffer
    : catalogue.lines[INFRA].default_offer;
  if (parsed.recommended_offer !== offer) {
    notes.push('offer taken from research (' + offer + '); the scoring model said "' +
      parsed.recommended_offer + '"');
  }

  // A lead without an address is a draft addressed to nobody. WF-05 does not
  // check for one - is_suppressed(NULL) is false, and the trigger on outreach
  // has nothing to compare - so the draft would reach pending_approval with no
  // recipient. The check belongs here, where the lead is created.
  const recipient = best && best.person_id && contactable(best) ? best
    : roleRecipient && roleRecipient.person_id ? roleRecipient
    : null;
  const lead = status !== 'suppressed' && recipient
    ? { person_id: recipient.person_id, score: total,
        reason: String(parsed.reason || '').slice(0, 400),
        recommended_offer: offer,
        status: 'new' }
    : null;
  if (!lead) {
    notes.push(
      status === 'suppressed' ? 'domain is suppressed, so no lead row was created'
      : !best ? 'no person on file, so no lead row was created'
      : 'person on file but no usable address, so no lead row was created');
  } else if (recipient === roleRecipient) {
    notes.push('lead created on the general address ' + roleRecipient.email +
      ': no named person has a usable address');
  }

  results.push({ index: i, line, json: {
    agent_run_id: req.agent_run_id,
    company_id: req.company_id,
    name: req.name,
    domain: req.domain,
    valid: true,
    errors: [],
    notes,
    overrides,
    error_message: null,
    scores: { fit_score: fit, research_score: research, decision_maker_score: dmScore,
              total_score: total, company_status: status },
    components: points,
    lead,
    model_output: parsed,
    raw_response: raw,
    usage,
  } });
}

// ---- one result per company: the better line -----------------------------
//
// Both lines use the same 0-100 scale and the same bands, so the totals compare
// directly. A tie goes to infrastructure, the line this pipeline has evidence
// for. A line whose model call failed loses to one that succeeded; only when
// both fail is the company an error.
const out = [];
const byCompany = new Map();
for (const r of results) {
  const id = r.json.company_id;
  if (!byCompany.has(id)) byCompany.set(id, []);
  byCompany.get(id).push(r);
}
for (const group of byCompany.values()) {
  const valid = group.filter((r) => r.json.valid);
  const pool = valid.length ? valid : group;
  const best = pool.slice().sort((a, b) =>
    ((b.json.scores ? b.json.scores.total_score : -1) - (a.json.scores ? a.json.scores.total_score : -1)) ||
    ((a.line === INFRA ? 0 : 1) - (b.line === INFRA ? 0 : 1)))[0];
  const summary = group.map((r) => r.line + ' ' +
    (r.json.valid ? r.json.scores.total_score : 'failed: ' + r.json.error_message)).join(', ');
  const json = { ...best.json, line: best.line,
                 line_scores: group.map((r) => ({ line: r.line, valid: r.json.valid,
                   total: r.json.valid ? r.json.scores.total_score : null,
                   components: r.json.components || null, overrides: r.json.overrides })) };
  if (group.length > 1) json.notes = [...(json.notes || []), 'lines: ' + summary + '; kept ' + best.line];
  out.push({ json, pairedItem: { item: best.index } });
}

return out;
